//! 🛫️ Controlled canonical physical Text emission.
use super::{RecordValue,RecordSpec,RecordLayout,FieldSpec,FieldValue,Shape,DslValue,Number,ExprValue,WireValue,WireNode,JoinMode,TextError};
use protocol::value::native_encoding::NativeEncodeControl;

/// 🖨️ Emits a declared physical record through caller-owned output admission.
pub fn print_controlled(value:&RecordValue,spec:&RecordSpec,mode:JoinMode,maximum_output_bytes:usize,control:&mut NativeEncodeControl<'_>)->Result<String,TextError>{
    control.scoped_stage(|control|->Result<_,String>{
        control.checkpoint()?;let mut measure=Emitter::new(mode,None,maximum_output_bytes);measure.record(value,spec,control)?;measure.newline(control)?;
        control.charge(measure.bytes)?;let mut output=String::new();output.try_reserve_exact(measure.bytes).map_err(|_|"native Text output allocation failed")?;
        let mut writer=Emitter::new(mode,Some(output),maximum_output_bytes);writer.record(value,spec,control)?;writer.newline(control)?;
        if writer.bytes!=measure.bytes{return Err("native Text emission disagrees with measured output".into())}Ok(writer.output.take().unwrap())
    }).map_err(|message|TextError{message,span:Default::default(),expected:None})
}

/// 🧮️ Emits a literal expression under the same owned output and recursive work control.
pub fn print_expr_controlled(value:&ExprValue,control:&mut NativeEncodeControl<'_>)->Result<String,TextError>{control.scoped_stage(|control|->Result<_,String>{control.checkpoint()?;let mut measure=Emitter::new(JoinMode::Inline,None,usize::MAX);measure.expression(value,0,control)?;control.charge(measure.bytes)?;let mut output=String::new();output.try_reserve_exact(measure.bytes).map_err(|_|"native expression output allocation failed")?;let mut writer=Emitter::new(JoinMode::Inline,Some(output),usize::MAX);writer.expression(value,0,control)?;if writer.bytes!=measure.bytes{return Err("native expression emission changed after admission".into())}Ok(writer.output.unwrap())}).map_err(|message|TextError{message,span:Default::default(),expected:None})}

struct Emitter { output:Option<String>, bytes:usize, maximum_output_bytes:usize, mode:JoinMode, indent:usize, line_open:bool, glued:bool }
impl Emitter {
    fn new(mode:JoinMode,output:Option<String>,maximum_output_bytes:usize)->Self{Self{output,bytes:0,maximum_output_bytes,mode,indent:0,line_open:false,glued:false}}
    fn raw(&mut self,text:&str,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.bytes=self.bytes.checked_add(text.len()).filter(|length|*length<=control.maximum_bytes().min(self.maximum_output_bytes)).ok_or("native Text output exceeds caller limit")?;if let Some(output)=self.output.as_ref(){if self.bytes>output.capacity(){return Err("native Text output exceeded measured allocation".into())}}if text.len()<=65536{if let Some(output)=self.output.as_mut(){output.push_str(text);}return Ok(())}control.scoped_stage(|control|->Result<_,String>{control.begin_stage(text.len())?;let mut start=0;while start<text.len(){let mut end=start.saturating_add(65536).min(text.len());while !text.is_char_boundary(end){end-=1;}if let Some(output)=self.output.as_mut(){output.push_str(&text[start..end]);}control.advance(end-start)?;start=end;}Ok(())})}
    fn begin_atom(&mut self,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if !self.line_open{if self.mode==JoinMode::Document{for _ in 0..self.indent{self.raw("  ",control)?;}}self.line_open=true;}else if !self.glued{self.raw(" ",control)?;}self.glued=false;Ok(())}
    fn atom(&mut self,text:&str,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.begin_atom(control)?;self.raw(text,control)}
    fn newline(&mut self,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if self.mode==JoinMode::Document&&self.line_open{self.raw("\n",control)?;self.line_open=false;}Ok(())}
    fn open(&mut self,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if self.mode==JoinMode::Inline{self.atom("{",control)}else{self.raw(if self.glued{"{"}else{" {"},control)?;self.raw("\n",control)?;self.line_open=false;self.glued=false;self.indent=self.indent.checked_add(1).ok_or("native Text indentation overflow")?;Ok(())}}
    fn close(&mut self,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if self.mode==JoinMode::Inline{self.atom("}",control)}else{self.newline(control)?;self.indent=self.indent.saturating_sub(1);for _ in 0..self.indent{self.raw("  ",control)?;}self.raw("}\n",control)}}
    fn inline<T>(&mut self,control:&mut NativeEncodeControl<'_>,operation:impl FnOnce(&mut Self,&mut NativeEncodeControl<'_>)->Result<T,String>)->Result<T,String>{let previous=(self.mode,self.indent,self.line_open,self.glued);self.mode=JoinMode::Inline;self.indent=0;self.line_open=false;self.glued=false;let result=operation(self,control);(self.mode,self.indent,self.line_open,self.glued)=previous;result}
    fn number(&mut self,value:impl std::fmt::Display,control:&mut NativeEncodeControl<'_>)->Result<(),String>{let mut buffer=StackText{bytes:[0;1088],length:0};std::fmt::write(&mut buffer,format_args!("{value}")).map_err(|_|"native numeric format exceeded bounded stack buffer")?;self.raw(buffer.text(),control)}
    fn float(&mut self,value:f64,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if value.is_nan(){let mut buffer=StackText{bytes:[0;1088],length:0};std::fmt::write(&mut buffer,format_args!("nan64_{:016x}",value.to_bits())).map_err(|_|"native IEEE formatting failed")?;self.raw(buffer.text(),control)}else{self.number(value,control)}}
    fn quoted(&mut self,text:&str,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.raw("\"",control)?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(text.len())?;for character in text.chars(){match character{'\\'=>self.raw("\\\\",control)?,'\"'=>self.raw("\\\"",control)?,'\n'=>self.raw("\\n",control)?,'\r'=>self.raw("\\r",control)?,'\t'=>self.raw("\\t",control)?,value if (value as u32)<32=>{self.raw("\\u{",control)?;let mut buffer=StackText{bytes:[0;1088],length:0};std::fmt::write(&mut buffer,format_args!("{:x}",value as u32)).map_err(|_|"native escape formatting failed")?;self.raw(buffer.text(),control)?;self.raw("}",control)?;},value=>{let mut bytes=[0;4];self.raw(value.encode_utf8(&mut bytes),control)?;}}control.advance(character.len_utf8())?;}Ok(())})?;self.raw("\"",control)}
    fn text(&mut self,text:&str,force_quote:bool,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if !force_quote&&bare_ident(text,control)?{control.scoped_stage(|control|->Result<_,String>{control.begin_stage(text.len())?;for character in text.chars(){let mut bytes=[0;4];self.raw(character.encode_utf8(&mut bytes),control)?;control.advance(character.len_utf8())?;}Ok(())})}else{self.quoted(text,control)}}
    fn octets(&mut self,bytes:&[u8],control:&mut NativeEncodeControl<'_>)->Result<(),String>{const ALPHABET:&[u8;64]=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";self.raw("\"",control)?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(bytes.len())?;for part in bytes.chunks(3){let a=part[0];let b=part.get(1).copied().unwrap_or(0);let c=part.get(2).copied().unwrap_or(0);let word=[ALPHABET[(a>>2)as usize],ALPHABET[((a&3)<<4|b>>4)as usize],if part.len()>1{ALPHABET[((b&15)<<2|c>>6)as usize]}else{b'='},if part.len()>2{ALPHABET[(c&63)as usize]}else{b'='}];self.raw(std::str::from_utf8(&word).map_err(|_|"invalid native base64 alphabet")?,control)?;control.advance(part.len())?;}Ok(())})?;self.raw("\"",control)}
    fn key(&mut self,key:&str,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.begin_atom(control)?;self.text(key,false,control)?;self.raw("=",control)?;self.glued=true;Ok(())}
    fn verbatim(&mut self,language:&str,text:&str,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.begin_atom(control)?;if self.mode==JoinMode::Inline{return self.quoted(text,control)}self.raw("```",control)?;self.raw(language,control)?;self.raw("\n",control)?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(text.len())?;for character in text.chars(){let mut bytes=[0;4];self.raw(character.encode_utf8(&mut bytes),control)?;control.advance(character.len_utf8())?;}Ok(())})?;if !text.is_empty(){self.raw("\n",control)?;}self.raw("```",control)}
    fn record(&mut self,value:&RecordValue,spec:&RecordSpec,control:&mut NativeEncodeControl<'_>)->Result<(),String>{control.scoped_depth(64,|control|->Result<_,String>{control.checkpoint()?;if spec.layout==RecordLayout::Call{let name=spec.fields.iter().find(|field|field.is_call_name).ok_or("native Call has no name field")?;let Some(FieldValue::Text(text))=value.get(name.id)else{return Err("native Call name is not Text".into())};self.begin_atom(control)?;self.text(text,false,control)?;self.atom("=",control)?;if let Some(keyword)=spec.keyword.as_deref(){self.atom(keyword,control)?;}self.raw("(",control)?;self.inline(control,|writer,control|writer.fields(value,spec,control))?;self.raw(")",control)}else{if let Some(keyword)=spec.keyword.as_deref(){self.atom(keyword,control)?;}self.fields(value,spec,control)}})}
    fn fields(&mut self,value:&RecordValue,spec:&RecordSpec,control:&mut NativeEncodeControl<'_>)->Result<(),String>{
        let mut fields=control.allocate_vec::<&FieldSpec>(spec.fields.len())?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(spec.fields.len().checked_mul(2).ok_or("native positional order workload overflow")?)?;let mut offsets=[0usize;256];let mut count=0usize;for field in &spec.fields{if let Some(position)=field.position.filter(|_|!field.is_call_name){offsets[position as usize]+=1;count+=1;}control.step()?;}let mut offset=0;for slot in &mut offsets{let next=offset+*slot;*slot=offset;offset=next;}if count>0{fields.resize(count,&spec.fields[0]);}for field in &spec.fields{if let Some(position)=field.position.filter(|_|!field.is_call_name){let slot=&mut offsets[position as usize];fields[*slot]=field;*slot+=1;}control.step()?;}Ok(())})?;
        for(index,field)in fields.iter().enumerate(){match value.get(field.id){Some(value)if !matches!(value,FieldValue::Absent)=>self.shape(value,&field.shape,control)?,_=>{if fields[index+1..].iter().any(|field|matches!(value.get(field.id),Some(value)if !matches!(value,FieldValue::Absent))){self.atom("_",control)?;}}}}
        fields.clear();control.scoped_stage(|control|->Result<_,String>{control.begin_stage(spec.fields.len().checked_mul(5).ok_or("native field order workload overflow")?)?;for rank in 0..5{for field in &spec.fields{if field.position.is_none()&&!field.key.is_empty()&&!field.is_call_name&&super::keyed_field_rank(&field.shape)==rank{fields.push(field);}control.step()?;}}Ok(())})?;
        for field in fields{let Some(item)=value.get(field.id).filter(|value|!matches!(value,FieldValue::Absent))else{continue};match &field.shape{
            Shape::EmbedFrom(key)=>{let language=spec.fields.iter().find(|field|field.key==*key).and_then(|field|value.get(field.id)).and_then(|value|if let FieldValue::Text(text)=value{Some(text.as_str())}else{None}).unwrap_or("plaintext");self.newline(control)?;self.key(&field.key,control)?;if let FieldValue::Text(text)=item{self.verbatim(language,text,control)?;}else{return Err("native EmbedFrom is not Text".into())}},
            Shape::Statements(_)=>self.shape(item,&field.shape,control)?,
            Shape::Block(_)=>{self.newline(control)?;self.atom(&field.key,control)?;self.shape(item,&field.shape,control)?;},
            Shape::Table(make)=>{self.newline(control)?;self.atom(&field.key,control)?;let FieldValue::List(items)=item else{return Err("native Table is not List".into())};self.table(items,&make.encode(control)?,true,control)?;},
            _=>{self.key(&field.key,control)?;self.shape(item,&field.shape,control)?;}
        }}Ok(())
    }
    fn table(&mut self,items:&[FieldValue],spec:&RecordSpec,columnar:bool,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.atom("[",control)?;if columnar{self.glued=true;for field in &spec.fields{self.begin_atom(control)?;self.raw(&field.key,control)?;self.raw(":",control)?;self.raw(super::shape_type_name(&field.shape),control)?;}self.glued=true;self.atom("]",control)?;self.open(control)?;}control.scoped_stage(|control|->Result<_,String>{control.begin_stage(items.len())?;for item in items{let FieldValue::Record(record)=item else{return Err("native table item is not Record".into())};if columnar{self.newline(control)?;for field in &spec.fields{match record.get(field.id){Some(value)if !matches!(value,FieldValue::Absent)=>{if matches!(field.shape,Shape::Record(_)){self.atom("{",control)?;self.glued=true;self.shape(value,&field.shape,control)?;self.glued=true;self.atom("}",control)?;}else{self.shape(value,&field.shape,control)?;}},_=>self.atom("_",control)?}}}else{self.atom("{",control)?;self.glued=true;self.record(record,spec,control)?;self.glued=true;self.atom("}",control)?;}control.step()?;}Ok(())})?;if columnar{self.close(control)}else{self.atom("]",control)}}
    fn shape(&mut self,value:&FieldValue,shape:&Shape,control:&mut NativeEncodeControl<'_>)->Result<(),String>{control.scoped_depth(64,|control|->Result<_,String>{control.checkpoint()?;match(value,shape){
        (FieldValue::Float(value),Shape::Quantity(unit)|Shape::Angle(unit))=>{self.begin_atom(control)?;self.float(*value,control)?;self.raw(unit.symbol,control)},
        (FieldValue::UInt(value),Shape::Count)=>{self.begin_atom(control)?;self.raw("x",control)?;self.number(value,control)},
        (FieldValue::Tuple(items),Shape::Coord(_)|Shape::Dir|Shape::Dim(_)|Shape::Range)=>{self.begin_atom(control)?;match shape{Shape::Coord(_)=>self.raw("@",control)?,Shape::Dir=>self.raw("^",control)?,Shape::Range=>self.raw("(",control)?,_=>{}}for(index,item)in items.iter().enumerate(){if index>0{self.raw(match shape{Shape::Dim(_)=>"x",Shape::Range if index==1=>"..",_=>","},control)?;}let FieldValue::Float(value)=item else{return Err("native numeric tuple element is not Float".into())};self.float(*value,control)?;}if matches!(shape,Shape::Range){self.raw(")",control)?;}Ok(())},
        (FieldValue::Expr(value),Shape::Expr)=>{self.begin_atom(control)?;self.raw("(",control)?;self.expression(value,0,control)?;self.raw(")",control)},
        (FieldValue::Text(value),Shape::Embed(language))=>self.verbatim(language,value,control),
        (FieldValue::Text(value),Shape::EmbedFrom(_))=>self.verbatim("plaintext",value,control),
        (FieldValue::Bool(value),_)=>self.atom(if *value{"true"}else{"false"},control),
        (FieldValue::Int(value),_)=>{self.begin_atom(control)?;self.number(value,control)},
        (FieldValue::UInt(value),_)=>{self.begin_atom(control)?;self.number(value,control)},
        (FieldValue::Float(value),_)=>{self.begin_atom(control)?;self.float(*value,control)},
        (FieldValue::Text(value),_)=>{self.begin_atom(control)?;self.text(value,false,control)},
        (FieldValue::Bytes64(value),_)=>{self.begin_atom(control)?;self.octets(value,control)},
        (FieldValue::Enum(ordinal),Shape::Enum(variants))=>{let(keyword,_)=variants.iter().find(|(_,value)|value==ordinal).ok_or("native enum ordinal is undeclared")?;self.atom(keyword,control)},
        (FieldValue::Tuple(items),Shape::Tuple(element,_))=>{self.begin_atom(control)?;for(index,item)in items.iter().enumerate(){if index>0{self.raw(",",control)?;}self.inline(control,|writer,control|writer.shape(item,element,control))?;}Ok(())},
        (FieldValue::List(items),Shape::Table(make))=>self.table(items,&make.encode(control)?,false,control),
        (FieldValue::List(items),Shape::List(element))=>{self.atom("[",control)?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(items.len())?;for item in items{control.scoped_stage(|control|->Result<_,String>{if matches!(element.as_ref(),Shape::Record(_)){self.atom("{",control)?;self.shape(item,element,control)?;self.atom("}",control)}else{self.shape(item,element,control)}})?;control.step()?;}Ok(())})?;self.atom("]",control)},
        (FieldValue::Record(value),Shape::Record(make))=>self.record(value,&make.encode(control)?,control),
        (FieldValue::Block(value),Shape::Block(shape))=>{self.open(control)?;self.shape(value,shape,control)?;self.close(control)},
        (FieldValue::Statements(items),Shape::Statements(variants))=>control.scoped_stage(|control|->Result<_,String>{control.begin_stage(items.len())?;for(keyword,record)in items{let(_,make)=variants.iter().find(|(name,_)|name==keyword).ok_or("native statement keyword is undeclared")?;self.newline(control)?;control.scoped_stage(|control|self.record(record,&make.encode(control)?,control))?;control.step()?;}Ok(())}),
        (FieldValue::Map(items),Shape::Map(shape))=>{let mut sorted=control.allocate_vec::<&(String,FieldValue)>(items.len())?;sorted.extend(items.iter());sort_keys(&mut sorted,|item|item.0.as_str(),control)?;self.open(control)?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(sorted.len())?;for(key,value)in sorted{control.scoped_stage(|control|->Result<_,String>{self.key(key,control)?;self.shape(value,shape,control)})?;control.step()?;}Ok(())})?;self.close(control)},
        (FieldValue::Value(value),Shape::Value)=>self.intrinsic(value,control),
        (FieldValue::Wire(value),Shape::Wire)=>self.wire(value,control),
        _=>Err("native field value disagrees with declared shape".into())
    }})}
    fn intrinsic(&mut self,value:&DslValue,control:&mut NativeEncodeControl<'_>)->Result<(),String>{control.scoped_depth(64,|control|->Result<_,String>{control.checkpoint()?;match value{
        DslValue::Null=>self.atom("null",control),DslValue::Bool(value)=>self.atom(if *value{"true"}else{"false"},control),
        DslValue::Number(Number::Int(value))=>{self.begin_atom(control)?;self.number(value,control)},DslValue::Number(Number::UInt(value))=>{self.begin_atom(control)?;self.number(value,control)},
        DslValue::Number(Number::Float(value))=>{self.begin_atom(control)?;let start=self.bytes;self.float(*value,control)?;if value.is_finite(){let mut buffer=StackText{bytes:[0;1088],length:0};std::fmt::write(&mut buffer,format_args!("{value}")).map_err(|_|"native float formatting failed")?;if !buffer.text().contains(['.','e','E'])&&self.bytes>start{self.raw(".0",control)?;}}Ok(())},
        DslValue::String(value)=>{self.begin_atom(control)?;self.quoted(value,control)},
        DslValue::Bytes(value)=>{self.begin_atom(control)?;self.raw("bytes64(",control)?;self.octets(value,control)?;self.raw(")",control)},
        DslValue::Array(items)=>{self.atom("[",control)?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(items.len())?;for value in items{control.scoped_stage(|control|self.intrinsic(value,control))?;control.step()?;}Ok(())})?;self.atom("]",control)},
        DslValue::Object(items)=>{let mut sorted=control.allocate_vec::<&(String,DslValue)>(items.len())?;sorted.extend(items.iter());sort_keys(&mut sorted,|item|item.0.as_str(),control)?;self.open(control)?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(sorted.len())?;for(key,value)in sorted{control.scoped_stage(|control|->Result<_,String>{self.key(key,control)?;self.intrinsic(value,control)})?;control.step()?;}Ok(())})?;self.close(control)}
    }})}
    fn expression(&mut self,value:&ExprValue,minimum:u8,control:&mut NativeEncodeControl<'_>)->Result<(),String>{control.scoped_depth(64,|control|->Result<_,String>{control.checkpoint()?;let precedence=match value{ExprValue::Neg(_)=>3,ExprValue::Binary(operator,_,_)=>operator.precedence(),_=>255};let bracket=precedence<minimum;if bracket{self.raw("(",control)?;}match value{ExprValue::Num(value)=>self.float(*value,control)?,ExprValue::Var(name)=>{self.text(name,false,control)?;},ExprValue::Neg(value)=>{self.raw("-",control)?;self.expression(value,4,control)?;},ExprValue::Binary(operator,left,right)=>{self.expression(left,precedence,control)?;self.raw(" ",control)?;self.raw(operator.symbol(),control)?;self.raw(" ",control)?;self.expression(right,precedence+1,control)?;},ExprValue::Call(name,items)=>{self.text(name,false,control)?;self.raw("(",control)?;control.scoped_stage(|control|->Result<_,String>{control.begin_stage(items.len())?;for(index,item)in items.iter().enumerate(){if index>0{self.raw(", ",control)?;}control.scoped_stage(|control|self.expression(item,0,control))?;control.step()?;}Ok(())})?;self.raw(")",control)?;}}if bracket{self.raw(")",control)?;}Ok(())})}
    fn wire_node(&mut self,value:&WireNode,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.raw(&value.id,control)?;if let Some(kind)=value.kind.as_deref(){self.raw(":",control)?;self.raw(kind,control)?;}if let Some(port)=value.port.as_deref(){self.raw("@",control)?;self.raw(port,control)?;}Ok(())}
    fn wire(&mut self,value:&WireValue,control:&mut NativeEncodeControl<'_>)->Result<(),String>{self.begin_atom(control)?;self.wire_node(&value.from,control)?;if let Some((directed,to))=value.edge.as_ref(){if value.edge_label.is_empty(){self.raw(if *directed{"->"}else{"--"},control)?;}else{self.raw(" -",control)?;if let Some(id)=value.edge_label.id.as_deref(){self.raw(id,control)?;}if let Some(kind)=value.edge_label.kind.as_deref(){self.raw(":",control)?;self.raw(kind,control)?;}self.raw(if *directed{">"}else{"-"},control)?;}self.wire_node(to,control)?;}if !matches!(&value.properties,DslValue::Object(items)if items.is_empty()){self.intrinsic(&value.properties,control)?;}Ok(())}
}

struct StackText { bytes:[u8;1088], length:usize }
impl StackText {fn text(&self)->&str{std::str::from_utf8(&self.bytes[..self.length]).unwrap()}}
impl std::fmt::Write for StackText{fn write_str(&mut self,text:&str)->std::fmt::Result{let end=self.length.checked_add(text.len()).filter(|end|*end<=self.bytes.len()).ok_or(std::fmt::Error)?;self.bytes[self.length..end].copy_from_slice(text.as_bytes());self.length=end;Ok(())}}

fn sort_keys<T>(items:&mut Vec<&T>,key:impl Fn(&T)->&str,control:&mut NativeEncodeControl<'_>)->Result<(),String>{if items.len()<2{return Ok(())}let mut scratch=control.allocate_vec::<&T>(items.len())?;scratch.extend(items.iter().copied());control.scoped_stage(|control|->Result<_,String>{control.begin_stage(0)?;let mut width=1usize;while width<items.len(){for start in (0..items.len()).step_by(width.saturating_mul(2)){let middle=start.saturating_add(width).min(items.len());let end=middle.saturating_add(width).min(items.len());let(mut left,mut right)=(start,middle);for output in start..end{let from_left=if left==middle{false}else if right==end{true}else{compare_keys(key(items[left]),key(items[right]),control)?!=std::cmp::Ordering::Greater};scratch[output]=if from_left{let value=items[left];left+=1;value}else{let value=items[right];right+=1;value};control.step()?;}}std::mem::swap(items,&mut scratch);width=width.checked_mul(2).ok_or("native key sort width overflow")?;}Ok(())})}
fn compare_keys(left:&str,right:&str,control:&mut NativeEncodeControl<'_>)->Result<std::cmp::Ordering,String>{control.scoped_stage(|control|->Result<_,String>{let count=left.len().min(right.len());control.begin_stage(count)?;let mut start=0;while start<count{let end=start.saturating_add(65536).min(count);let order=left.as_bytes()[start..end].cmp(&right.as_bytes()[start..end]);control.advance(end-start)?;if order!=std::cmp::Ordering::Equal{return Ok(order)}start=end;}Ok(left.len().cmp(&right.len()))})}

fn bare_ident(text:&str,control:&mut NativeEncodeControl<'_>)->Result<bool,String>{control.scoped_stage(|control|->Result<_,String>{control.begin_stage(text.len())?;if text.len()>crate::os_dsl::Limits::default().max_bytes||matches!(text,"_"|"true"|"false"|"null"|"nan"|"inf"){return Ok(false)}for(prefix,width)in[("nan64_",16),("nan32_",8)]{if let Some(rest)=text.strip_prefix(prefix){if rest.len()>=width&&rest.as_bytes()[..width].iter().all(u8::is_ascii_hexdigit){return Ok(false)}}}for prefix in ["inf","nan"]{if let Some(suffix)=text.strip_prefix(prefix){if crate::os_dsl::unit_by_symbol(suffix).is_some(){return Ok(false)}}}let mut characters=text.chars().peekable();let Some(first)=characters.next()else{return Ok(false)};if !(first.is_alphabetic()||first=='_'){return Ok(false)}control.advance(first.len_utf8())?;while let Some(value)=characters.next(){if !(value.is_alphanumeric()||matches!(value,'_'|'-'|'.'|'/'))||(value=='-'&&characters.peek().is_some_and(|next|matches!(*next,'>'|'-'))){return Ok(false)}control.advance(value.len_utf8())?;}Ok(true)})}
